) -> Iterable[bytes]:
    # GET only reads the most recent probe result; it never performs an
    # attempt and writes no state.
    result = mirror_probe_store.get(raw_id)
    if result is None:
        return _error(
            start_response,
            "404 Not Found",
            "probe_not_found",
            "No probe has been performed for this mirror.",
        )
    return _json_response(
