        not isinstance(signed_digest, str)
        or _DIGEST_PATTERN.fullmatch(signed_digest) is None
    ):
        return (
            "400 Bad Request",
            "invalid_request",
            f"{_SIGNED_DIGEST_HEADER_NAME} header must be a 64-character "
            "hexadecimal string.",
