    if key_id not in policy.keys:
        return (
            "403 Forbidden",
            "key_not_trusted",
            "The key id is not trusted by the mirror signature policy.",
        )

    if policy.cover_digest and signed_digest != digest:
        return (
            "403 Forbidden",
            "digest_uncovered",
            "The signed digest does not cover the pulled layer digest.",
        )

